### Step 4: Creating the JS File (`script.js`)
This adds interactivity: Dynamic content, form validation, active nav highlighting, and error handling.

```javascript
// Shared JS for all pages
document.addEventListener('DOMContentLoaded', function() {
    // Highlight active nav link based on current page
    const currentPage = window.location.pathname.split('/').pop() || 'index.html';
    const navLinks = document.querySelectorAll('nav a');
    navLinks.forEach(link => {
        link.classList.remove('active');
        if (link.getAttribute('href') === currentPage) {
            link.classList.add('active');
        }
    });

    // Sample project data (simulating API)
    const projects = [
        { title: 'Project 1', desc: 'A web app built with React.', link: '#' },
        { title: 'Project 2', desc: 'Mobile-first e-commerce site.', link: '#' },
        { title: 'Project 3', desc: 'Data visualization dashboard.', link: '#' }
    ];

    // Populate teaser projects on homepage
    if (document.getElementById('project-list')) {
        const projectList = document.getElementById('project-list');
        projects.forEach(project => {
            const card = document.createElement('div');
            card.classList.add('project-card');
            card.innerHTML = `<h3>${project.title}</h3><p>${project.desc}</p><a href="${project.link}">View</a>`;
            projectList.appendChild(card);
        });
    }

    // Populate detailed projects (with simulated delay for complexity)
    if (document.getElementById('detailed-projects')) {
        const detailedProjects = document.getElementById('detailed-projects');
        // Simulate async fetch with delay
        setTimeout(() => {
            projects.forEach((project, index) => {
                const card = document.createElement('div');
                card.classList.add('project-card');
                card.innerHTML = `<h3>${project.title}</h3><p>${project.desc} (Detail: Advanced features in ${index + 1}).</p><a href="${project.link}">View</a>`;
                detailedProjects.appendChild(card);
            });
        }, 1000); // 1s delay to test loading states
    }

    // Form validation on contact page
    if (document.getElementById('contact-form')) {
        const form = document.getElementById('contact-form');
        const messageDiv = document.getElementById('form-message');

        form.addEventListener('submit', function(e) {
            e.preventDefault();
            const name = document.getElementById('name').value.trim();
            const email = document.getElementById('email').value.trim();
            const message = document.getElementById('message').value.trim();

            if (!name || !email || !message) {
                messageDiv.innerHTML = '<p style="color: red;">Please fill all fields!</p>';
                return;
            }

            if (!email.includes('@')) {
                messageDiv.innerHTML = '<p style="color: red;">Invalid email!</p>';
                return;
            }

            // Simulate form submission (store in localStorage for persistence)
            localStorage.setItem('contactForm', JSON.stringify({ name, email, message }));
            messageDiv.innerHTML = '<p style="color: green;">Message sent successfully!</p>';
            form.reset();
        });
    }

    // Error handling example: Log any JS errors
    window.addEventListener('error', function(e) {
        console.error('JS Error:', e.message);
    });
});
```

**Process Explanation**: Used `DOMContentLoaded` for safe DOM access. Integrated event listeners for nav, dynamic population (with timeout for async simulation), and form validation (regex-like checks). localStorage adds persistence. This tests complex integration like cross-page state and error handling.

